function longestSemiRepetitiveSubstring(s) {
  let left = 0;
  let pairs = 0;
  let best = 1;

  for (let right = 1; right < s.length; right++) {
    if (s[right] === s[right - 1]) {
      pairs++;
    }
    while (pairs > 1) {
      if (s[left] === s[left + 1]) {
        pairs--;
      }
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

