function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 10);
  // A small alphabet makes neighbouring repeats common, so the window has to shrink often.
  const alphabet = rand() < 0.5 ? 2 + Math.floor(rand() * 2) : 10;
  let s = '';
  for (let i = 0; i < n; i++) s += String(Math.floor(rand() * alphabet));
  return [s];
}
